// Package sanitize makes untrusted issue text inert before it reaches the
// terminal. Every issue and comment body goes through Body before Markdown
// rendering, every title goes through Title, and renderer output goes through
// Rendered, so only SGR and OSC 8 sequences generated by the renderer reach
// the terminal.
package sanitize

import (
	"fmt"
	"html"
	"strings"
	"unicode/utf8"

	"github.com/charmbracelet/x/ansi"
)

// TabWidth is the distance between tab stops when Body expands tabs.
const TabWidth = 4

// Body returns Markdown source with every control made visible: CRLF line
// endings become LF, tabs expand to the next tab stop, and every other C0
// control (CR, ESC, BEL, …), DEL, C1 control, bidi control and invalid UTF-8
// byte becomes a printable marker. A character reference such as &#27; that
// would decode to one of those during rendering is replaced the same way,
// because the renderer decodes references in text and code spans.
func Body(s string) string {
	s = strings.ReplaceAll(s, "\r\n", "\n")
	w := writer{}
	w.b.Grow(len(s))
	for i := 0; i < len(s); {
		if s[i] == '&' {
			if n, dec := unsafeReference(s[i:]); n > 0 {
				for _, r := range dec {
					w.rune(r)
				}
				i += n
				continue
			}
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		i += size
		w.rune(r) // an invalid byte decodes to U+FFFD and shows as such
	}
	return w.b.String()
}

// Title is Body for single-line text such as issue titles: line breaks
// become ␤ as well.
func Title(s string) string {
	return strings.ReplaceAll(Body(s), "\n", "␤")
}

// Marker returns the visible replacement for a control rune: a Unicode
// Control Picture for C0 controls and DEL (␛ ␇ ␍ …), and ⟨U+XXXX⟩ otherwise.
func Marker(r rune) string {
	switch {
	case r < 0x20:
		return string(0x2400 + r)
	case r == 0x7f:
		return "␡"
	default:
		return fmt.Sprintf("⟨U+%04X⟩", r)
	}
}

type writer struct {
	b        strings.Builder
	col      int // display column at measured
	measured int // offset in b up to which col is known
}

func (w *writer) rune(r rune) {
	switch {
	case r == '\n':
		w.b.WriteByte('\n')
		w.measured, w.col = w.b.Len(), 0
	case r == '\t':
		w.col += ansi.StringWidth(w.b.String()[w.measured:])
		n := TabWidth - w.col%TabWidth
		w.b.WriteString(strings.Repeat(" ", n))
		w.col += n
		w.measured = w.b.Len()
	case isControl(r):
		w.b.WriteString(Marker(r))
	default:
		w.b.WriteRune(r)
	}
}

// unsafeReference returns the length of the character reference at the
// start of s and its decoding when it decodes to a control, or 0. It decodes
// exactly as the renderer does (html.UnescapeString), including numeric
// references without a semicolon.
func unsafeReference(s string) (int, string) {
	n := 1
	isDigit := func(c byte) bool { return c >= '0' && c <= '9' }
	isHex := func(c byte) bool { return isDigit(c) || (c|0x20 >= 'a' && c|0x20 <= 'f') }
	isAlnum := func(c byte) bool { return isDigit(c) || (c|0x20 >= 'a' && c|0x20 <= 'z') }
	accept := isAlnum
	if n < len(s) && s[n] == '#' {
		n++
		accept = isDigit
		if n < len(s) && (s[n] == 'x' || s[n] == 'X') {
			n++
			accept = isHex
		}
	}
	start := n
	for n < len(s) && n < 40 && accept(s[n]) {
		n++
	}
	if n == start {
		return 0, ""
	}
	if n < len(s) && s[n] == ';' {
		n++
	}
	tok := s[:n]
	dec := html.UnescapeString(tok)
	if dec == tok {
		return 0, ""
	}
	for _, r := range dec {
		if r != '\n' && isControl(r) {
			return n, dec
		}
	}
	return 0, ""
}

// Rendered returns renderer output in which only SGR sequences (CSI … m)
// and OSC 8 hyperlinks survive; every other escape sequence, control,
// C1/bidi control and invalid byte becomes a marker. Body already keeps
// content from producing controls; this is the last line of defence against
// anything the renderer itself might decode.
func Rendered(s string) string {
	if clean(s) {
		return s
	}
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); {
		if s[i] == 0x1b {
			if n := allowedSequence(s[i:]); n > 0 {
				b.WriteString(s[i : i+n])
				i += n
				continue
			}
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		i += size
		switch {
		case r == utf8.RuneError && size == 1:
			b.WriteRune(utf8.RuneError)
		case r != '\n' && isControl(r):
			b.WriteString(Marker(r))
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// clean reports whether s has no escape or control at all (the common case
// for plain lines), so Rendered can return it without copying.
func clean(s string) bool {
	for i := 0; i < len(s); i++ {
		if c := s[i]; c < 0x20 && c != '\n' || c >= 0x7f {
			return false
		}
	}
	return true
}

// allowedSequence returns the length of an SGR or OSC 8 sequence at the
// start of s, or 0.
func allowedSequence(s string) int {
	if strings.HasPrefix(s, "\x1b[") {
		n := 2
		for n < len(s) && (s[n] >= '0' && s[n] <= '9' || s[n] == ';' || s[n] == ':') {
			n++
		}
		if n < len(s) && s[n] == 'm' {
			return n + 1
		}
		return 0
	}
	if !strings.HasPrefix(s, "\x1b]8;") {
		return 0
	}
	for i := 4; i < len(s); {
		switch {
		case s[i] == 0x07:
			return i + 1
		case strings.HasPrefix(s[i:], "\x1b\\"):
			return i + 2
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		if (r == utf8.RuneError && size == 1) || isControl(r) {
			return 0
		}
		i += size
	}
	return 0
}

// isControl reports runes that must not reach the terminal from content.
func isControl(r rune) bool {
	return r < 0x20 || r == 0x7f || (r >= 0x80 && r <= 0x9f) || isBidi(r)
}

func isBidi(r rune) bool {
	return (r >= 0x202a && r <= 0x202e) || (r >= 0x2066 && r <= 0x2069) || r == 0x200e || r == 0x200f || r == 0x061c
}
